import torch
import torch.nn as nn
from cutegen.ptx_runtime import PtxModule, i32, u32, i64, u64, f32, f64
PTX_SOURCE = r"""
.version 8.0
.target sm_89
.address_size 64
.shared .align 16 .b32 sA[1024];    // double-buffered: 2 x (16 x 32) tiles of A
.shared .align 16 .b32 sB[1024];    // double-buffered: 2 x (32 x 16) tiles of B
.visible .entry ut_triu_matmul_f32(
    .param .u64 A_ptr,
    .param .u64 B_ptr,
    .param .u64 C_ptr,
    .param .u32 N_param
)
{
    .reg .pred %p_i_in, %p_j_in, %p_valid, %p_upper, %p_kdone, %pA0_i, %pA0_k, %pA0, %pA1_i, %pA1_k, %pA1, %pB0_k, %pB0_j, %pB0, %pB1_k, %pB1_j, %pB1, %p_compute, %p_lt0, %p_gt0, %p_gt1, %p_empty, %p_tdone, %p_cta_lower, %p_has_next, %p_has_next2, %p_wait1;
    .reg .b32 %rBx, %rBy, %rTx, %rTy, %rBDx, %rBDy, %rBlockCol, %rj, %rBlockRow, %ri, %rN, %rZero, %rKTILE, %rMTILE, %rNTILE, %rNm1, %rTidLin, %rKB, %rIdxA0, %rRowA0, %rColA0, %rIGlobA0, %rKGlobA0, %rAO0, %rIdxA1, %rRowA1, %rColA1, %rIGlobA1, %rKGlobA1, %rAO1, %rIdxB0, %rRowB0, %rColB0, %rKGlobB0, %rJGlobB0, %rBO0, %rIdxB1, %rRowB1, %rColB1, %rKGlobB1, %rJGlobB1, %rBO1, %rStart, %rEnd, %rKBEnd, %rLocalStart, %rLocalEnd, %rT, %rOffAIdx, %rOffBIdx, %rCbase, %rCidx, %rBDxM1, %rBlockColEnd, %rKBNext, %rKBpp, %rStage, %rStageOffBytes, %rNextStage, %rNextStageOffBytes, %rWaitDepth, %rKBase;
    .reg .b64 %rdA, %rdB, %rdC, %rd_sA, %rd_sB, %rdAO0, %rdAPtr0, %rdSA0, %rdSAPtr0, %rdAO1, %rdAPtr1, %rdSA1, %rdSAPtr1, %rdBO0, %rdBPtr0, %rdSB0, %rdSBPtr0, %rdBO1, %rdBPtr1, %rdSB1, %rdSBPtr1, %rdOffA, %rdPtrA, %rdOffB, %rdPtrB, %rdCoff, %rdCptr, %rd_sA_cur, %rd_sB_cur, %rd_sA_dest, %rd_sB_dest, %rdOffStage, %rdOffStageN;
    .reg .f32 %fAcc, %fA0, %fA1, %fB0, %fB1, %fAt, %fBt, %fOut;
    // Load parameters
    ld.param.u64 %rdA, [A_ptr];
    ld.param.u64 %rdB, [B_ptr];
    ld.param.u64 %rdC, [C_ptr];
    ld.param.u32 %rN,  [N_param];
    // Thread/block indices and dimensions
    mov.u32 %rBx, %ctaid.x;
    mov.u32 %rBy, %ctaid.y;
    mov.u32 %rTx, %tid.x;
    mov.u32 %rTy, %tid.y;
    mov.u32 %rBDx, %ntid.x;   // expect 16
    mov.u32 %rBDy, %ntid.y;   // expect 16
    // Compute global row/col for this thread (i=row, j=col)
    mul.lo.u32 %rBlockCol, %rBx, %rBDx;   // blockIdx.x * blockDim.x
    add.u32    %rj, %rBlockCol, %rTx;     // j index
    mul.lo.u32 %rBlockRow, %rBy, %rBDy;   // blockIdx.y * blockDim.y
    add.u32    %ri, %rBlockRow, %rTy;     // i index
    // Predicates
    setp.lt.u32 %p_i_in, %ri, %rN;
    setp.lt.u32 %p_j_in, %rj, %rN;
    and.pred    %p_valid, %p_i_in, %p_j_in;   // thread writes only if valid
    setp.le.u32 %p_upper, %ri, %rj;           // only upper-triangular outputs are computed
    // CTA-level early zero for tiles strictly below the upper-triangular band
    add.u32 %rBDxM1, %rBDx, 0xffffffff;      // blockDim.x - 1
    add.u32 %rBlockColEnd, %rBlockCol, %rBDxM1; // last column covered by this CTA
    setp.gt.u32 %p_cta_lower, %rBlockRow, %rBlockColEnd; // entire tile is lower-triangular
    @!%p_cta_lower bra CONTINUE_COMPUTE;
CTA_ZERO:
    @!%p_valid bra CTA_DONE;
    mov.f32 %fOut, 0f00000000;
    mul.lo.u32   %rCbase, %ri, %rN;     // ri * N
    add.u32      %rCidx, %rCbase, %rj;  // i*N + j
    mul.wide.u32 %rdCoff, %rCidx, 4;
    add.s64      %rdCptr, %rdC, %rdCoff;
    st.global.f32 [%rdCptr], %fOut;
CTA_DONE:
    ret;
CONTINUE_COMPUTE:
    // Prepare shared memory base pointers
    mov.u64 %rd_sA, sA;
    mov.u64 %rd_sB, sB;
    // Accumulator
    mov.f32 %fAcc, 0f00000000;
    // Precompute constants
    mov.u32 %rZero, 0;
    mov.u32 %rKTILE, 32; // K tile size
    mov.u32 %rMTILE, 16; // M tile (blockDim.y)
    mov.u32 %rNTILE, 16; // N tile (blockDim.x)
    add.u32 %rNm1, %rN, 0xffffffff; // N-1
    // Linear thread id within CTA
    mad.lo.u32 %rTidLin, %rTy, %rBDx, %rTx;  // rTy*blockDim.x + rTx
    // Initialize K and stage
    mov.u32 %rKB, 0;
    mov.u32 %rStage, 0;
    // Warmup prefetch: Tile 0 -> stage 0
    // Set destination bases for stage 0
    mul.lo.u32 %rStageOffBytes, %rStage, 2048;  // 512 elems * 4B
    cvt.u64.u32 %rdOffStage, %rStageOffBytes;
    add.s64 %rd_sA_dest, %rd_sA, %rdOffStage;
    add.s64 %rd_sB_dest, %rd_sB, %rdOffStage;
    mov.u32 %rKBase, %rKB;
    // ---- Async copies for A tile (tile 0) ----
    add.u32 %rIGlobA0, %rBlockRow, %rTy;
    add.u32 %rKGlobA0, %rKBase, %rTx;
    setp.lt.u32 %pA0_i, %rIGlobA0, %rN;
    setp.lt.u32 %pA0_k, %rKGlobA0, %rN;
    and.pred %pA0, %pA0_i, %pA0_k;
    mul.lo.u32   %rAO0, %rIGlobA0, %rN;
    add.u32      %rAO0, %rAO0, %rKGlobA0;
    mul.wide.u32 %rdAO0, %rAO0, 4;
    add.s64      %rdAPtr0, %rdA, %rdAO0;
    shl.b32 %rOffAIdx, %rTx, 4;          // (k_local)*16
    add.u32 %rOffAIdx, %rOffAIdx, %rTy;  // + row
    mul.wide.u32 %rdOffA, %rOffAIdx, 4;
    add.s64 %rdPtrA, %rd_sA_dest, %rdOffA;
    @%pA0 cp.async.ca.shared.global [%rdPtrA], [%rdAPtr0], 4;
    @!%pA0 st.shared.f32 [%rdPtrA], 0f00000000;
    // Pass 1 for A
    add.u32 %rColA1, %rTx, 16;
    add.u32 %rKGlobA1, %rKBase, %rColA1;
    setp.lt.u32 %pA1_i, %rIGlobA0, %rN;
    setp.lt.u32 %pA1_k, %rKGlobA1, %rN;
    and.pred %pA1, %pA1_i, %pA1_k;
    mul.lo.u32   %rAO1, %rIGlobA0, %rN;
    add.u32      %rAO1, %rAO1, %rKGlobA1;
    mul.wide.u32 %rdAO1, %rAO1, 4;
    add.s64      %rdAPtr1, %rdA, %rdAO1;
    shl.b32 %rOffAIdx, %rColA1, 4;       // (k_local2)*16
    add.u32 %rOffAIdx, %rOffAIdx, %rTy;  // + row
    mul.wide.u32 %rdOffA, %rOffAIdx, 4;
    add.s64 %rdPtrA, %rd_sA_dest, %rdOffA;
    @%pA1 cp.async.ca.shared.global [%rdPtrA], [%rdAPtr1], 4;
    @!%pA1 st.shared.f32 [%rdPtrA], 0f00000000;
    // ---- Async copies for B tile (tile 0) ----
    add.u32 %rJGlobB0, %rBlockCol, %rTx;
    add.u32 %rKGlobB0, %rKBase, %rTy;
    setp.lt.u32 %pB0_k, %rKGlobB0, %rN;
    setp.lt.u32 %pB0_j, %rJGlobB0, %rN;
    and.pred %pB0, %pB0_k, %pB0_j;
    mul.lo.u32   %rBO0, %rKGlobB0, %rN;
    add.u32      %rBO0, %rBO0, %rJGlobB0;
    mul.wide.u32 %rdBO0, %rBO0, 4;
    add.s64      %rdBPtr0, %rdB, %rdBO0;
    shl.b32 %rOffBIdx, %rTx, 5;          // n_local*32
    add.u32 %rOffBIdx, %rOffBIdx, %rTy;  // + k_local
    mul.wide.u32 %rdOffB, %rOffBIdx, 4;
    add.s64 %rdPtrB, %rd_sB_dest, %rdOffB;
    @%pB0 cp.async.ca.shared.global [%rdPtrB], [%rdBPtr0], 4;
    @!%pB0 st.shared.f32 [%rdPtrB], 0f00000000;
    // Pass 1 for B
    add.u32 %rRowB1, %rTy, 16;
    add.u32 %rKGlobB1, %rKBase, %rRowB1;
    setp.lt.u32 %pB1_k, %rKGlobB1, %rN;
    setp.lt.u32 %pB1_j, %rJGlobB0, %rN;
    and.pred %pB1, %pB1_k, %pB1_j;
    mul.lo.u32   %rBO1, %rKGlobB1, %rN;
    add.u32      %rBO1, %rBO1, %rJGlobB0;
    mul.wide.u32 %rdBO1, %rBO1, 4;
    add.s64      %rdBPtr1, %rdB, %rdBO1;
    shl.b32 %rOffBIdx, %rTx, 5;          // n_local*32
    add.u32 %rOffBIdx, %rOffBIdx, %rRowB1; // + k_local2
    mul.wide.u32 %rdOffB, %rOffBIdx, 4;
    add.s64 %rdPtrB, %rd_sB_dest, %rdOffB;
    @%pB1 cp.async.ca.shared.global [%rdPtrB], [%rdBPtr1], 4;
    @!%pB1 st.shared.f32 [%rdPtrB], 0f00000000;
    // Commit group for tile 0
    cp.async.commit_group;
    // Prefetch tile 1 if exists -> stage 1
    add.u32 %rKBNext, %rKB, 32;
    setp.lt.u32 %p_has_next, %rKBNext, %rN;
    @!%p_has_next bra SKIP_WARMUP_NEXT;
    xor.b32 %rNextStage, %rStage, 1;
    mul.lo.u32 %rNextStageOffBytes, %rNextStage, 2048;
    cvt.u64.u32 %rdOffStageN, %rNextStageOffBytes;
    add.s64 %rd_sA_dest, %rd_sA, %rdOffStageN;
    add.s64 %rd_sB_dest, %rd_sB, %rdOffStageN;
    mov.u32 %rKBase, %rKBNext;
    // ---- Async copies for A tile (tile 1) ----
    add.u32 %rIGlobA0, %rBlockRow, %rTy;
    add.u32 %rKGlobA0, %rKBase, %rTx;
    setp.lt.u32 %pA0_i, %rIGlobA0, %rN;
    setp.lt.u32 %pA0_k, %rKGlobA0, %rN;
    and.pred %pA0, %pA0_i, %pA0_k;
    mul.lo.u32   %rAO0, %rIGlobA0, %rN;
    add.u32      %rAO0, %rAO0, %rKGlobA0;
    mul.wide.u32 %rdAO0, %rAO0, 4;
    add.s64      %rdAPtr0, %rdA, %rdAO0;
    shl.b32 %rOffAIdx, %rTx, 4;
    add.u32 %rOffAIdx, %rOffAIdx, %rTy;
    mul.wide.u32 %rdOffA, %rOffAIdx, 4;
    add.s64 %rdPtrA, %rd_sA_dest, %rdOffA;
    @%pA0 cp.async.ca.shared.global [%rdPtrA], [%rdAPtr0], 4;
    @!%pA0 st.shared.f32 [%rdPtrA], 0f00000000;
    add.u32 %rColA1, %rTx, 16;
    add.u32 %rKGlobA1, %rKBase, %rColA1;
    setp.lt.u32 %pA1_i, %rIGlobA0, %rN;
    setp.lt.u32 %pA1_k, %rKGlobA1, %rN;
    and.pred %pA1, %pA1_i, %pA1_k;
    mul.lo.u32   %rAO1, %rIGlobA0, %rN;
    add.u32      %rAO1, %rAO1, %rKGlobA1;
    mul.wide.u32 %rdAO1, %rAO1, 4;
    add.s64      %rdAPtr1, %rdA, %rdAO1;
    shl.b32 %rOffAIdx, %rColA1, 4;
    add.u32 %rOffAIdx, %rOffAIdx, %rTy;
    mul.wide.u32 %rdOffA, %rOffAIdx, 4;
    add.s64 %rdPtrA, %rd_sA_dest, %rdOffA;
    @%pA1 cp.async.ca.shared.global [%rdPtrA], [%rdAPtr1], 4;
    @!%pA1 st.shared.f32 [%rdPtrA], 0f00000000;
    // ---- Async copies for B tile (tile 1) ----
    add.u32 %rJGlobB0, %rBlockCol, %rTx;
    add.u32 %rKGlobB0, %rKBase, %rTy;
    setp.lt.u32 %pB0_k, %rKGlobB0, %rN;
    setp.lt.u32 %pB0_j, %rJGlobB0, %rN;
    and.pred %pB0, %pB0_k, %pB0_j;
    mul.lo.u32   %rBO0, %rKGlobB0, %rN;
    add.u32      %rBO0, %rBO0, %rJGlobB0;
    mul.wide.u32 %rdBO0, %rBO0, 4;
    add.s64      %rdBPtr0, %rdB, %rdBO0;
    shl.b32 %rOffBIdx, %rTx, 5;
    add.u32 %rOffBIdx, %rOffBIdx, %rTy;
    mul.wide.u32 %rdOffB, %rOffBIdx, 4;
    add.s64 %rdPtrB, %rd_sB_dest, %rdOffB;
    @%pB0 cp.async.ca.shared.global [%rdPtrB], [%rdBPtr0], 4;
    @!%pB0 st.shared.f32 [%rdPtrB], 0f00000000;
    add.u32 %rRowB1, %rTy, 16;
    add.u32 %rKGlobB1, %rKBase, %rRowB1;
    setp.lt.u32 %pB1_k, %rKGlobB1, %rN;
    setp.lt.u32 %pB1_j, %rJGlobB0, %rN;
    and.pred %pB1, %pB1_k, %pB1_j;
    mul.lo.u32   %rBO1, %rKGlobB1, %rN;
    add.u32      %rBO1, %rBO1, %rJGlobB0;
    mul.wide.u32 %rdBO1, %rBO1, 4;
    add.s64      %rdBPtr1, %rdB, %rdBO1;
    shl.b32 %rOffBIdx, %rTx, 5;
    add.u32 %rOffBIdx, %rOffBIdx, %rRowB1;
    mul.wide.u32 %rdOffB, %rOffBIdx, 4;
    add.s64 %rdPtrB, %rd_sB_dest, %rdOffB;
    @%pB1 cp.async.ca.shared.global [%rdPtrB], [%rdBPtr1], 4;
    @!%pB1 st.shared.f32 [%rdPtrB], 0f00000000;
    // Commit group for tile 1
    cp.async.commit_group;
SKIP_WARMUP_NEXT:
    // Set current stage bases for compute (stage 0 initially)
    mul.lo.u32 %rStageOffBytes, %rStage, 2048;
    cvt.u64.u32 %rdOffStage, %rStageOffBytes;
    add.s64 %rd_sA_cur, %rd_sA, %rdOffStage;
    add.s64 %rd_sB_cur, %rd_sB, %rdOffStage;
    // Initialize wait depth flag: 1 if next tile was prefetched, else 0
    selp.b32 %rWaitDepth, 1, 0, %p_has_next;
MAIN_LOOP:
    // Wait for appropriate number of groups: 1 if we have a prefetched next tile, else 0
    setp.eq.u32 %p_wait1, %rWaitDepth, 1;
    @%p_wait1 bra DO_WAIT1;
    cp.async.wait_group 0;
    bra AFTER_WAIT;
DO_WAIT1:
    cp.async.wait_group 1;
AFTER_WAIT:
    // Synchronize to ensure current tile is visible
    bar.sync 0;
    // Accumulate this K tile contribution if this output is valid upper-triangular
    and.pred %p_compute, %p_valid, %p_upper;
    @!%p_compute bra SKIP_ACCUM;
    // Compute start and end k for this tile: [max(i,KB), min(j, KB+KTILE-1, N-1)]
    mov.u32 %rStart, %ri;
    setp.lt.u32 %p_lt0, %rStart, %rKB;
    @%p_lt0 mov.u32 %rStart, %rKB;              // rStart = max(ri, KB)
    mov.u32 %rEnd, %rj;
    setp.gt.u32 %p_gt0, %rEnd, %rNm1;
    @%p_gt0 mov.u32 %rEnd, %rNm1;               // rEnd = min(rj, N-1)
    add.u32 %rKBEnd, %rKB, 31;
    setp.gt.u32 %p_gt1, %rEnd, %rKBEnd;
    @%p_gt1 mov.u32 %rEnd, %rKBEnd;             // rEnd = min(rEnd, KB+31)
    // If rStart > rEnd, nothing to do in this tile
    setp.gt.u32 %p_empty, %rStart, %rEnd;
    @%p_empty bra AFTER_ACCUM;
    sub.u32 %rLocalStart, %rStart, %rKB;
    sub.u32 %rLocalEnd,   %rEnd,   %rKB;
    mov.u32 %rT, %rLocalStart;
ACCUM_LOOP:
    setp.gt.u32 %p_tdone, %rT, %rLocalEnd;
    @%p_tdone bra AFTER_ACCUM;
    // Load A_smem_cur[ t*16 + row_local ]
    shl.b32 %rOffAIdx, %rT, 4;            // t * 16
    add.u32 %rOffAIdx, %rOffAIdx, %rTy;   // + row
    mul.wide.u32 %rdOffA, %rOffAIdx, 4;
    add.s64 %rdPtrA, %rd_sA_cur, %rdOffA;
    ld.shared.f32 %fAt, [%rdPtrA];
    // Load B_smem_cur[ col_local*32 + t ]
    shl.b32 %rOffBIdx, %rTx, 5;           // col * 32
    add.u32 %rOffBIdx, %rOffBIdx, %rT;    // + t
    mul.wide.u32 %rdOffB, %rOffBIdx, 4;
    add.s64 %rdPtrB, %rd_sB_cur, %rdOffB;
    ld.shared.f32 %fBt, [%rdPtrB];
    // FMA
    fma.rn.f32 %fAcc, %fAt, %fBt, %fAcc;
    add.u32 %rT, %rT, 1;
    bra ACCUM_LOOP;
AFTER_ACCUM:
SKIP_ACCUM:
    // Synchronize before switching stages and issuing next prefetch
    bar.sync 0;
    // Advance to next tile
    add.u32 %rKB, %rKB, 32;
    setp.ge.u32 %p_kdone, %rKB, %rN;
    @%p_kdone bra K_DONE;
    // Toggle current stage for compute
    xor.b32 %rStage, %rStage, 1;
    mul.lo.u32 %rStageOffBytes, %rStage, 2048;
    cvt.u64.u32 %rdOffStage, %rStageOffBytes;
    add.s64 %rd_sA_cur, %rd_sA, %rdOffStage;
    add.s64 %rd_sB_cur, %rd_sB, %rdOffStage;
    // Prefetch the tile after the next (keep one group in flight): rKBpp = rKB + 32
    add.u32 %rKBpp, %rKB, 32;
    setp.lt.u32 %p_has_next2, %rKBpp, %rN;
    @!%p_has_next2 bra NO_PREFETCH_NEXT;
    // Destination is the other stage (not current)
    xor.b32 %rNextStage, %rStage, 1;
    mul.lo.u32 %rNextStageOffBytes, %rNextStage, 2048;
    cvt.u64.u32 %rdOffStageN, %rNextStageOffBytes;
    add.s64 %rd_sA_dest, %rd_sA, %rdOffStageN;
    add.s64 %rd_sB_dest, %rd_sB, %rdOffStageN;
    mov.u32 %rKBase, %rKBpp;
    // ---- Async copies for A tile (future) ----
    add.u32 %rIGlobA0, %rBlockRow, %rTy;
    add.u32 %rKGlobA0, %rKBase, %rTx;
    setp.lt.u32 %pA0_i, %rIGlobA0, %rN;
    setp.lt.u32 %pA0_k, %rKGlobA0, %rN;
    and.pred %pA0, %pA0_i, %pA0_k;
    mul.lo.u32   %rAO0, %rIGlobA0, %rN;
    add.u32      %rAO0, %rAO0, %rKGlobA0;
    mul.wide.u32 %rdAO0, %rAO0, 4;
    add.s64      %rdAPtr0, %rdA, %rdAO0;
    shl.b32 %rOffAIdx, %rTx, 4;
    add.u32 %rOffAIdx, %rOffAIdx, %rTy;
    mul.wide.u32 %rdOffA, %rOffAIdx, 4;
    add.s64 %rdPtrA, %rd_sA_dest, %rdOffA;
    @%pA0 cp.async.ca.shared.global [%rdPtrA], [%rdAPtr0], 4;
    @!%pA0 st.shared.f32 [%rdPtrA], 0f00000000;
    add.u32 %rColA1, %rTx, 16;
    add.u32 %rKGlobA1, %rKBase, %rColA1;
    setp.lt.u32 %pA1_i, %rIGlobA0, %rN;
    setp.lt.u32 %pA1_k, %rKGlobA1, %rN;
    and.pred %pA1, %pA1_i, %pA1_k;
    mul.lo.u32   %rAO1, %rIGlobA0, %rN;
    add.u32      %rAO1, %rAO1, %rKGlobA1;
    mul.wide.u32 %rdAO1, %rAO1, 4;
    add.s64      %rdAPtr1, %rdA, %rdAO1;
    shl.b32 %rOffAIdx, %rColA1, 4;
    add.u32 %rOffAIdx, %rOffAIdx, %rTy;
    mul.wide.u32 %rdOffA, %rOffAIdx, 4;
    add.s64 %rdPtrA, %rd_sA_dest, %rdOffA;
    @%pA1 cp.async.ca.shared.global [%rdPtrA], [%rdAPtr1], 4;
    @!%pA1 st.shared.f32 [%rdPtrA], 0f00000000;
    // ---- Async copies for B tile (future) ----
    add.u32 %rJGlobB0, %rBlockCol, %rTx;
    add.u32 %rKGlobB0, %rKBase, %rTy;
    setp.lt.u32 %pB0_k, %rKGlobB0, %rN;
    setp.lt.u32 %pB0_j, %rJGlobB0, %rN;
    and.pred %pB0, %pB0_k, %pB0_j;
    mul.lo.u32   %rBO0, %rKGlobB0, %rN;
    add.u32      %rBO0, %rBO0, %rJGlobB0;
    mul.wide.u32 %rdBO0, %rBO0, 4;
    add.s64      %rdBPtr0, %rdB, %rdBO0;
    shl.b32 %rOffBIdx, %rTx, 5;
    add.u32 %rOffBIdx, %rOffBIdx, %rTy;
